#include <bits/stdc++.h>
using namespace std;

class Solution {public:int minimumLines(vector<vector<int>>& stockPrices){sort(stockPrices.begin(),stockPrices.end());int n=stockPrices.size();if(n<2)return 0;int ans=1;for(int i=2;i<n;++i){long long dx1=stockPrices[i-1][0]-stockPrices[i-2][0],dy1=stockPrices[i-1][1]-stockPrices[i-2][1],dx2=stockPrices[i][0]-stockPrices[i-1][0],dy2=stockPrices[i][1]-stockPrices[i-1][1];if(dy1*dx2!=dy2*dx1)++ans;}return ans;} };
